if set(_MESSAGES) != set(LANGUAGES):
    raise RuntimeError("Queue Manager translations must define every supported language.")

_REQUIRED_KEYS = set(_MESSAGES[DEFAULT_LANGUAGE])
for _language, _catalog in _MESSAGES.items():
    if set(_catalog) != _REQUIRED_KEYS:
        raise RuntimeError(f"Incomplete Queue Manager translations for {_language}.")


def translate_queue_manager(language: str | None, key: str, **values: Any) -> str:
    """Translate Queue Manager copy with English fallback and safe formatting."""
    locale = normalize_language(language)
    template = _MESSAGES.get(locale, {}).get(
        key, _MESSAGES[DEFAULT_LANGUAGE].get(key, key)
    )
    try:
        return template.format(**values)
    except (KeyError, ValueError):
        return template
